import{_ as d,o as e,c as a,ag as i}from"./chunks/framework.CtWPcAmt.js";const p=JSON.parse('{"title":"附录 C：权限分级与安全检查清单","description":"L0–L3 权限分级定义、任务前/中/后的安全检查清单、高风险动作红线。","frontmatter":{"title":"附录 C：权限分级与安全检查清单","description":"L0–L3 权限分级定义、任务前/中/后的安全检查清单、高风险动作红线。","layout":"doc","lastUpdated":true},"headers":[],"relativePath":"appendix/02-permission-checklist.md","filePath":"appendix/02-permission-checklist.md","lastUpdated":null}'),r={name:"appendix/02-permission-checklist.md"};function l(o,t,n,s,h,c){return e(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="附录-c-权限分级与安全检查清单" tabindex="-1">附录 C：权限分级与安全检查清单 <a class="header-anchor" href="#附录-c-权限分级与安全检查清单" aria-label="Permalink to &quot;附录 C：权限分级与安全检查清单&quot;">​</a></h1><h2 id="权限分级速查-对应第-8-章" tabindex="-1">权限分级速查（对应第 8 章） <a class="header-anchor" href="#权限分级速查-对应第-8-章" aria-label="Permalink to &quot;权限分级速查（对应第 8 章）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>允许什么</th><th>典型操作</th><th>新手建议</th></tr></thead><tbody><tr><td><strong>L0 只读</strong></td><td>读取、分析、总结</td><td>读文件、查资料、出建议</td><td>从这级开始</td></tr><tr><td><strong>L1 写入（限定目录）</strong></td><td>在指定目录建/改文件</td><td>输出文档、整理素材</td><td>输出到独立 <code>output/</code></td></tr><tr><td><strong>L2 执行</strong></td><td>运行命令/脚本</td><td>批量操作、跑脚本</td><td>默认关闭，白名单制</td></tr><tr><td><strong>L3 外部操作</strong></td><td>联网、发送、发布、付款</td><td>发邮件、下单、删远程</td><td>永远人工确认</td></tr></tbody></table><h2 id="任务前安全检查" tabindex="-1">任务前安全检查 <a class="header-anchor" href="#任务前安全检查" aria-label="Permalink to &quot;任务前安全检查&quot;">​</a></h2><ul><li>[ ] 已建独立目录：<code>任务名/input/</code>、<code>output/</code>、<code>backup/</code>；</li><li>[ ] 关键文件已备份（原文件复制到 <code>backup/</code>）；</li><li>[ ] 权限卡已写（读取/写入/执行/外部四行允许与禁止）；</li><li>[ ] 已记录输入基线（如 SHA-256 哈希，用于事后比对）；</li><li>[ ] 任务卡约束里写明了读取范围、写入位置、联网策略；</li><li>[ ] 任务卡里没有粘贴密码、Token、身份证号等敏感信息。</li></ul><h2 id="任务中检查-按监督档位" tabindex="-1">任务中检查（按监督档位） <a class="header-anchor" href="#任务中检查-按监督档位" aria-label="Permalink to &quot;任务中检查（按监督档位）&quot;">​</a></h2><ul><li>[ ] Agent 是否只读允许范围？（看它的动作/日志，不只看弹窗）</li><li>[ ] 是否出现未授权的联网/执行/写入？</li><li>[ ] 是否反复重试同一失败操作（&gt;2 次应插话）？</li><li>[ ] 分段确认点是否到了？到了就停下来验收。</li><li>[ ] 权限弹窗出现：看不懂就先拒绝，查清楚再授权。</li></ul><h2 id="任务后检查-边界验收" tabindex="-1">任务后检查（边界验收） <a class="header-anchor" href="#任务后检查-边界验收" aria-label="Permalink to &quot;任务后检查（边界验收）&quot;">​</a></h2><ul><li>[ ] 产物数量、名称、位置与任务卡交付物一致；</li><li>[ ] 输入文件哈希与基线一致（7/7、8/8 等）；</li><li>[ ] 读取/写入记录中没有越界项（有则记录并评估影响）；</li><li>[ ] <code>output/</code> 之外的目录没有被创建或修改；</li><li>[ ] 产物中没有泄漏账号、路径、密钥信息；</li><li>[ ] 所有「未核实」信息已标注，没有被写成事实。</li></ul><h2 id="高风险动作红线-永远人工确认-不做成自动步骤" tabindex="-1">高风险动作红线（永远人工确认，不做成自动步骤） <a class="header-anchor" href="#高风险动作红线-永远人工确认-不做成自动步骤" aria-label="Permalink to &quot;高风险动作红线（永远人工确认，不做成自动步骤）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动作</th><th>处理</th></tr></thead><tbody><tr><td>删除、覆盖、格式化</td><td>先备份；人工确认后才执行</td></tr><tr><td>发送、发布、对外提交</td><td>内容验收合格 ≠ 可以发布；发布动作人来做</td></tr><tr><td>付款、购买</td><td>永远人工执行最后一步</td></tr><tr><td>提供敏感信息</td><td>不写入任务卡；用变量/外部配置</td></tr><tr><td>运行不认识的脚本</td><td>先审内容，再决定是否运行</td></tr></tbody></table><h2 id="反直觉提醒-实测教训" tabindex="-1">反直觉提醒（实测教训） <a class="header-anchor" href="#反直觉提醒-实测教训" aria-label="Permalink to &quot;反直觉提醒（实测教训）&quot;">​</a></h2><ul><li><strong>没有权限弹窗 ≠ 没有越权行为</strong>（第 5 章 Qoder/Hermes 实测）；</li><li><strong>自检通过 ≠ 结果合格</strong>（第 5 章 Qoder 自检漏报实测）——边界验收必须独立于 Agent 的自检；</li><li><strong>最终状态正确 ≠ 过程合规</strong>（第 5 章 Hermes 误写后自动恢复实测）——过程记录与结果分开评价。</li></ul>',13)])])}const b=d(r,[["render",l]]);export{p as __pageData,b as default};
